// §6 golden surface: 10 cases × light/dark = 20 refs.
//
// Lives OUTSIDE test/ on purpose — the default `flutter test` never runs it,
// and dev-machine rendering (newer SDK) is irrelevant: refs are generated by
// the `goldens:generate` CI job on the pinned image and compared by `goldens`
// in the same image (see .gitlab-ci.yml). Hand-committing locally rendered
// refs is prohibited; they would only decode against this machine's SDK.
@Tags(['golden'])
library;

import 'dart:ffi' show DynamicLibrary;

import 'package:core/core.dart';
import 'package:data/data.dart';
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:local_budget/features/ledger/balance_strip.dart';
import 'package:local_budget/features/ledger/empty_month.dart';
import 'package:local_budget/features/ledger/transaction_row.dart';
import 'package:local_budget/features/ledger/view_models.dart';
import 'package:local_budget/main.dart';
import 'package:sqlite3/open.dart' as sqlite3_open;

import 'golden_harness.dart';

void main() {
  sqlite3_open.open.overrideFor(
    sqlite3_open.OperatingSystem.linux,
    () => DynamicLibrary.open('libsqlite3.so.0'),
  );

  setUpAll(loadRoboto);

  Money usd(int cents) => Money(cents, Currency.resolve('USD'));

  Future<void> pumpFullApp(
    WidgetTester tester,
    Brightness brightness,
    LedgerRepository repo,
  ) async {
    await tester.pumpWidget(
      LocalBudgetApp(
        repository: repo,
        theme: goldTheme(Brightness.light),
        darkTheme: goldTheme(Brightness.dark),
        themeMode: brightness == Brightness.light
            ? ThemeMode.light
            : ThemeMode.dark,
      ),
    );
    await tester.pumpAndSettle();
  }

  group('TransactionRow goldens', () {
    final tiles = <String, EntryTile>{
      'expense_memo': EntryTile(
        id: 1,
        icon: Icons.local_cafe,
        title: 'Coffee',
        memo: 'With Ana',
        amount: usd(1240),
        kind: EntryKind.expense,
        day: DateTime(2025, 5, 8),
      ),
      'income_plain': EntryTile(
        id: 2,
        icon: Icons.payments,
        title: 'Salary',
        amount: usd(240000),
        kind: EntryKind.income,
        day: DateTime(2025, 5, 9),
      ),
      'long_memo': EntryTile(
        id: 3,
        icon: Icons.local_grocery_store,
        title: 'Groceries',
        memo:
            'Weekly run — oat milk, rye bread, olive oil, dishwasher tabs and '
            'the good coffee Ana keeps asking for',
        amount: usd(8455),
        kind: EntryKind.expense,
        day: DateTime(2025, 5, 8),
      ),
    };

    for (final brightness in Brightness.values) {
      final mode = modeName(brightness);
      for (final entry in tiles.entries) {
        testWidgets('${entry.key} — $mode', (tester) async {
          usePhoneViewport(tester);
          await tester.pumpWidget(
            goldHost(
              brightness: brightness,
              child: TransactionRow(tile: entry.value),
            ),
          );
          await tester.pumpAndSettle();
          await expectLater(
            find.byType(TransactionRow),
            matchesGoldenFile('goldens/txn_${entry.key}_$mode.png'),
          );
        });
      }

      testWidgets('expense_memo at 1.3× text scale — $mode', (tester) async {
        usePhoneViewport(tester);
        tester.platformDispatcher.textScaleFactorTestValue = 1.3;
        addTearDown(tester.platformDispatcher.clearTextScaleFactorTestValue);
        await tester.pumpWidget(
          goldHost(
            brightness: brightness,
            child: TransactionRow(tile: tiles['expense_memo']!),
          ),
        );
        await tester.pumpAndSettle();
        await expectLater(
          find.byType(TransactionRow),
          matchesGoldenFile('goldens/txn_expense_memo_scaled_$mode.png'),
        );
      });
    }
  });

  group('BalanceStrip goldens', () {
    final summaries = <String, BalanceSummary>{
      'zero': BalanceSummary(income: usd(0), expenses: usd(0)),
      'typical': BalanceSummary(income: usd(240000), expenses: usd(550425)),
      'seven_digit': BalanceSummary(
        income: usd(123456789),
        expenses: usd(98765432),
      ),
    };

    for (final brightness in Brightness.values) {
      final mode = modeName(brightness);
      for (final entry in summaries.entries) {
        testWidgets('${entry.key} — $mode', (tester) async {
          usePhoneViewport(tester);
          await tester.pumpWidget(
            goldHost(
              brightness: brightness,
              child: BalanceStrip(summary: entry.value),
            ),
          );
          await tester.pumpAndSettle();
          await expectLater(
            find.byType(BalanceStrip),
            matchesGoldenFile('goldens/strip_${entry.key}_$mode.png'),
          );
        });
      }
    }
  });

  group('EmptyMonth goldens', () {
    for (final brightness in Brightness.values) {
      final mode = modeName(brightness);
      testWidgets('empty month — $mode', (tester) async {
        usePhoneViewport(tester);
        await tester.pumpWidget(
          goldHost(brightness: brightness, child: const EmptyMonth()),
        );
        await tester.pumpAndSettle();
        await expectLater(
          find.byType(EmptyMonth),
          matchesGoldenFile('goldens/empty_month_$mode.png'),
        );
      });
    }
  });

  group('QuickAddSheet goldens', () {
    for (final brightness in Brightness.values) {
      final mode = modeName(brightness);

      testWidgets('empty sheet — $mode', (tester) async {
        usePhoneViewport(tester);
        final db = AppDatabase.inMemory();
        final repo = LedgerRepository(db);
        try {
          await repo.ensureDefaults();
          await pumpFullApp(tester, brightness, repo);
          await tester.tap(find.byType(FloatingActionButton));
          await tester.pumpAndSettle();
          await expectLater(
            find.byType(BottomSheet),
            matchesGoldenFile('goldens/quickadd_empty_$mode.png'),
          );
        } finally {
          await db.close();
        }
      });

      testWidgets('entered amount + selected category — $mode', (tester) async {
        usePhoneViewport(tester);
        final db = AppDatabase.inMemory();
        final repo = LedgerRepository(db);
        try {
          await repo.ensureDefaults();
          await pumpFullApp(tester, brightness, repo);
          await tester.tap(find.byType(FloatingActionButton));
          await tester.pumpAndSettle();
          for (final key in ['1', '2', 'dot', '4', '0']) {
            await tester.tap(find.byKey(Key('keypad-$key')));
            await tester.pump();
          }
          await tester.tap(find.widgetWithText(FilterChip, 'Food'));
          await tester.pumpAndSettle();
          await expectLater(
            find.byType(BottomSheet),
            matchesGoldenFile('goldens/quickadd_entered_$mode.png'),
          );
        } finally {
          await db.close();
        }
      });
    }
  });
}
